p=[],setup=_=>{createCanvas(w=600,w);r=random;g=loadImage('https://openprocessing.org/sketch/2701912/files/p.png',_=>{g.loadPixels();for(y=w;y-=5;)for(x=w;x-=5;)if(alpha(g.get(x,y)))p.push([r(w),r(w),x,y])})}
draw=_=>{clear();for(i in p)[a,b,X,Y]=p[i],circle(a+=(X-a)/20,b+=(Y-b)/20,4),p[i]=[a,b,X,Y]}
